package com.studybuddy.api.api;
import com.studybuddy.api.api.ApiDtos.*; import com.studybuddy.api.domain.GroupMembership; import com.studybuddy.api.security.CurrentUser; import com.studybuddy.api.service.GroupService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/groups")
public class GroupController { private final CurrentUser current; private final GroupService groups; public GroupController(CurrentUser current,GroupService groups){this.current=current;this.groups=groups;} @GetMapping public List<GroupResponse> list(Authentication a,@RequestParam(required=false) Long courseId){return groups.list(current.require(a),courseId);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public GroupResponse create(Authentication a,@Valid @RequestBody GroupRequest r){return groups.create(current.require(a),r);} @PostMapping("/{id}/join-requests") @ResponseStatus(HttpStatus.NO_CONTENT) public void join(Authentication a,@PathVariable Long id){groups.requestJoin(current.require(a),id);} @GetMapping("/{id}/memberships") public List<Map<String,Object>> memberships(Authentication a,@PathVariable Long id){return groups.memberships(current.require(a),id).stream().map(m->Map.<String,Object>of("id",m.getId(),"userId",m.getUser().getId(),"status",m.getStatus().name(),"coordinator",m.isCoordinator())).toList();} @PostMapping("/{id}/memberships/{membershipId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void decide(Authentication a,@PathVariable Long id,@PathVariable Long membershipId,@RequestParam boolean approve){groups.decide(current.require(a),id,membershipId,approve);} @PostMapping("/{id}/leave") @ResponseStatus(HttpStatus.NO_CONTENT) public void leave(Authentication a,@PathVariable Long id){groups.leave(current.require(a),id);} @GetMapping("/{id}/sessions") public List<SessionResponse> sessions(Authentication a,@PathVariable Long id){return groups.sessions(current.require(a),id);} @PostMapping("/{id}/sessions") @ResponseStatus(HttpStatus.CREATED) public SessionResponse session(Authentication a,@PathVariable Long id,@Valid @RequestBody SessionRequest r){return groups.createSession(current.require(a),id,r);} @GetMapping("/{id}/messages") public List<MessageResponse> messages(Authentication a,@PathVariable Long id){return groups.messages(current.require(a),id);} @PostMapping("/{id}/messages") @ResponseStatus(HttpStatus.CREATED) public MessageResponse message(Authentication a,@PathVariable Long id,@Valid @RequestBody MessageRequest r){return groups.addMessage(current.require(a),id,r);} }
